from pydantic import BaseModel, Field, Literal, validator
from datetime import datetime
from typing import Tuple, Optional
from src.transplant_twin.domain.units import convert

class DataProvenance(BaseModel):
    source: str
    transformations: Tuple[str, ...] = tuple()
    synthetic: bool

class Observation(BaseModel):
    value: Optional[float] = None
    unit: str
    timestamp: datetime
    source: str
    confidence: float = Field(..., ge=0, le=1)
    missingness: Literal['observed', 'missing']
    provenance: DataProvenance

    @validator('value')
    def validate_value(cls, v, values):
        if v is not None and v < 0:
            raise ValueError('Value must be non-negative if present.')
        return v

    @validator('confidence')
    def validate_confidence(cls, v):
        if v < 0 or v > 1:
            raise ValueError('Confidence must be between 0 and 1.')
        return v

